INSERT INTO t_user_role(user_id,role_id,create_time,update_time,del_flag) SELECT u.id,r.id,NOW(),NOW(),0 FROM t_user u CROSS JOIN t_role r WHERE u.username='admin' AND u.status='active' AND u.del_flag=0 AND r.code='superAdmin' AND r.status='active' AND r.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_user_role ur WHERE ur.user_id=u.id AND ur.role_id=r.id AND ur.del_flag=0);

INSERT INTO t_role_permission(role_id,permission_id,create_time,update_time,del_flag) SELECT r.id,p.id,NOW(),NOW(),0 FROM t_role r CROSS JOIN t_permission p WHERE r.code='superAdmin' AND r.status='active' AND r.del_flag=0 AND p.status='active' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_role_permission rp WHERE rp.role_id=r.id AND rp.permission_id=p.id AND rp.del_flag=0);

INSERT INTO t_role_menu(role_id,menu_id,create_time,update_time,del_flag) SELECT r.id,m.id,NOW(),NOW(),0 FROM t_role r CROSS JOIN t_menu m WHERE r.code='superAdmin' AND r.status='active' AND r.del_flag=0 AND m.status='active' AND m.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_role_menu rm WHERE rm.role_id=r.id AND rm.menu_id=m.id AND rm.del_flag=0);
